[hidden] { display: none !important; }
:root { color-scheme: light; --ink:#203936; --green:#316c58; --mint:#dcebe0; --cream:#fffaf0; --orange:#e58b4d; --road:#687c72; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; display:grid; place-items:center; padding:24px 16px; background-color:#dce7d7; background-image:radial-gradient(#b5cbb7 1.5px,transparent 1.5px); background-size:18px 18px; color:var(--ink); font-family:system-ui,-apple-system,"Segoe UI",sans-serif; font-size:16px; }
.board-card { width:min(720px,100%); padding:32px; background:var(--cream); border:3px solid var(--ink); border-radius:18px; box-shadow:8px 8px 0 var(--ink); }
.header { text-align:center; }
.eyebrow { margin:0 0 8px; color:var(--green); font-size:14px; font-weight:800; letter-spacing:.12em; }
h1 { margin:0; font-size:clamp(28px,6vw,42px); line-height:1.1; letter-spacing:-.04em; }
.subtitle { margin:10px 0 24px; color:#597069; }
.toolbar { display:grid; grid-template-columns:1fr auto minmax(150px,200px); gap:12px; align-items:center; margin-bottom:18px; }
.counts { display:flex; gap:16px; flex-wrap:wrap; }
.count { display:flex; align-items:center; gap:7px; white-space:nowrap; }
.count strong { font-size:20px; }
.count-dot { width:11px; height:11px; border:2px solid var(--ink); border-radius:50%; }
.free-dot { background:var(--mint); }.occupied-dot { background:var(--orange); }
.search-label { font-weight:700; }
input { min-width:0; width:100%; padding:11px 12px; border:2px solid #a7b9ab; border-radius:9px; background:white; color:var(--ink); font:inherit; }
input:focus-visible,button:focus-visible,.space:focus-visible { outline:3px solid var(--orange); outline-offset:3px; }
.lot { position:relative; padding:20px 16px 14px; border:3px solid var(--ink); border-radius:12px; background:var(--road); }
.lane-mark { margin:0 0 14px; color:#e4eee2; text-align:center; font-size:14px; font-weight:800; letter-spacing:.13em; }
.spaces { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:10px; }
.space { min-height:112px; padding:8px 5px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:7px; border:2px dashed #f5f0d8; border-radius:8px; background:rgba(255,255,255,.08); color:white; cursor:pointer; font:inherit; transition:background .15s,transform .15s,box-shadow .15s; }
.space:hover { background:rgba(255,255,255,.19); transform:translateY(-2px); }
.space:active { transform:translateY(1px) scale(.98); }
.space .number { align-self:flex-start; margin-left:4px; color:#e5eddf; font-size:14px; font-weight:800; }
.car { width:43px; height:52px; position:relative; display:grid; place-items:center; border:2px solid var(--ink); border-radius:13px 13px 9px 9px; background:var(--orange); box-shadow:inset 0 -5px rgba(32,57,54,.15); }
.car::before,.car::after { content:""; position:absolute; left:-4px; width:4px; height:10px; border-radius:3px; background:var(--ink); box-shadow:47px 0 var(--ink); }
.car::before { top:9px; }.car::after { bottom:8px; }
.car-window { width:25px; height:18px; border:2px solid var(--ink); border-radius:7px 7px 4px 4px; background:#dcebe0; }
.plate-tag { max-width:100%; overflow:hidden; padding:2px 4px; border:1px solid var(--ink); border-radius:3px; background:var(--cream); color:var(--ink); font-size:12px; font-weight:800; text-overflow:ellipsis; white-space:nowrap; }
.space.occupied { border-style:solid; background:rgba(255,255,255,.1); }
.space.highlight { background:#d99a46; box-shadow:0 0 0 3px var(--cream),0 0 0 6px var(--orange); }
.exit-mark { margin-top:14px; color:#e4eee2; text-align:right; font-size:14px; font-weight:800; letter-spacing:.12em; }
.exit-mark span { display:inline-block; padding:3px 8px; border:2px solid #e4eee2; border-radius:4px; }
.message { min-height:24px; margin:16px 0 14px; text-align:center; color:#597069; }
footer { padding-top:14px; border-top:2px solid #e2e8dc; color:#597069; text-align:center; font-size:12px; font-weight:800; letter-spacing:.08em; }
dialog { width:min(420px,calc(100% - 32px)); padding:26px; border:3px solid var(--ink); border-radius:14px; background:var(--cream); color:var(--ink); box-shadow:8px 8px 0 var(--ink); }
dialog::backdrop { background:rgba(22,43,39,.58); }
dialog h2 { margin:0 0 18px; font-size:24px; }
dialog label { display:block; margin-bottom:7px; font-weight:700; }
.dialog-actions { display:flex; justify-content:flex-end; gap:10px; margin-top:18px; }
.button { padding:10px 15px; border:2px solid var(--ink); border-radius:8px; cursor:pointer; font:inherit; font-weight:750; transition:transform .12s,filter .12s; }
.button:hover { filter:brightness(1.06); }.button:active { transform:translateY(2px); }
.primary { background:var(--green); color:white; }.secondary { background:var(--mint); color:var(--ink); }
@media (max-width:600px) { .board-card { padding:24px 16px; }.toolbar { grid-template-columns:1fr 1fr; }.counts { grid-column:1/-1; justify-content:center; }.search-label { text-align:right; }.lot { padding:16px 10px 12px; }.spaces { grid-template-columns:repeat(4,minmax(0,1fr)); gap:8px; }.space { min-height:96px; } }
@media (max-width:380px) { .board-card { padding:20px 12px; }.counts { gap:12px; }.space { min-height:84px; }.car { transform:scale(.9); margin:-2px 0; } }

const spacesElement = document.getElementById('spaces');
const freeCount = document.getElementById('free-count');
const occupiedCount = document.getElementById('occupied-count');
const searchInput = document.getElementById('search-input');
const message = document.getElementById('message');
const dialog = document.getElementById('plate-dialog');
const form = document.getElementById('plate-form');
const plateInput = document.getElementById('plate-input');
const cancelButton = document.getElementById('cancel-button');
const cars = Array(12).fill(null);
let selectedSpace = null;

function render() {
  spacesElement.replaceChildren();
  let occupied = 0;
  cars.forEach((plate, index) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = `space${plate ? ' occupied' : ''}`;
    button.dataset.index = index;
    button.setAttribute('aria-label', plate ? `Space ${index + 1}, occupied by ${plate}. Activate to remove car.` : `Space ${index + 1}, free. Activate to park a car.`);
    button.setAttribute('aria-pressed', String(Boolean(plate)));
    const number = document.createElement('span');
    number.className = 'number';
    number.textContent = String(index + 1).padStart(2, '0');
    button.append(number);
    if (plate) {
      occupied++;
      const car = document.createElement('span');
      car.className = 'car';
      car.setAttribute('aria-hidden', 'true');
      const window = document.createElement('span');
      window.className = 'car-window';
      car.append(window);
      const tag = document.createElement('span');
      tag.className = 'plate-tag';
      tag.textContent = plate;
      button.append(car, tag);
    } else {
      const label = document.createElement('span');
      label.textContent = 'FREE';
      label.style.fontWeight = '800';
      label.style.letterSpacing = '.08em';
      button.append(label);
    }
    if (plate && searchInput.value.trim() && plate.toLowerCase().includes(searchInput.value.trim().toLowerCase())) button.classList.add('highlight');
    spacesElement.append(button);
  });
  occupiedCount.textContent = occupied;
  freeCount.textContent = cars.length - occupied;
}

spacesElement.addEventListener('click', event => {
  const button = event.target.closest('.space');
  if (!button) return;
  const index = Number(button.dataset.index);
  if (cars[index]) {
    const removed = cars[index];
    cars[index] = null;
    message.textContent = `Removed ${removed} from space ${index + 1}.`;
    render();
  } else {
    selectedSpace = index;
    plateInput.value = '';
    dialog.showModal();
    plateInput.focus();
  }
});

form.addEventListener('submit', event => {
  event.preventDefault();
  const plate = plateInput.value.trim();
  if (!plate || selectedSpace === null) return;
  cars[selectedSpace] = plate.toUpperCase();
  message.textContent = `Parked ${cars[selectedSpace]} in space ${selectedSpace + 1}.`;
  selectedSpace = null;
  dialog.close();
  render();
});

cancelButton.addEventListener('click', () => dialog.close());
dialog.addEventListener('close', () => { selectedSpace = null; });
searchInput.addEventListener('input', () => render());
render();
